import{_ as n,C as r,c as s,o as t,a2 as a,b as d,w as o,a as c,G as l,a3 as u}from"./chunks/framework.DkPtUiZm.js";const k=JSON.parse('{"title":"Contribution","description":"","frontmatter":{},"headers":[],"relativePath":"contribuer/conventions.md","filePath":"contribuer/conventions.md","lastUpdated":1790233006000}'),p={name:"contribuer/conventions.md"};function m(h,e,b,g,v,q){const i=r("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="contribution" tabindex="-1">Contribution <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;Contribution&quot;">​</a></h1><p>Ce document porte les <strong>règles de fond</strong> : ce qu&#39;un composant doit garantir, où va chaque chose, et pourquoi. La marche à suivre pratique — installer, lancer les vérifications, ouvrir une pull request — vit dans le <code>CONTRIBUTING.md</code> à la racine du dépôt, là où GitHub la propose au moment de contribuer.</p><p>Les deux ne se recopient pas : celui-ci dit quoi respecter, l&#39;autre comment s&#39;y prendre.</p><h2 id="signalements" tabindex="-1">Signalements <a class="header-anchor" href="#signalements" aria-label="Permalink to &quot;Signalements&quot;">​</a></h2><p><code>.github/ISSUE_TEMPLATE/</code> porte deux gabarits, et ils demandent chacun ce qui manque le plus souvent :</p><ul><li><strong>Anomalie</strong> — par quel canal le code est arrivé, et la sortie de <code>sia-ui doctor</code>. Un composant copié vit dans le dépôt de qui l&#39;a installé : sans savoir s&#39;il a été retouché, on cherche un défaut qui n&#39;est pas le nôtre. <code>sia-ui diff</code> répond à cette question en une commande.</li><li><strong>Composant ou variante</strong> — où le besoin s&#39;est déjà présenté, et ce qui différait d&#39;une fois à l&#39;autre. SIA UI n&#39;ajoute pas une entrée parce qu&#39;elle existe ailleurs, mais parce qu&#39;un besoin se répète; et ce qui diffère devient une prop, ou ne doit surtout pas être uniformisé.</li></ul><p>Le gabarit de pull request reprend les sept vérifications de la CI, et ajoute celles qui ne sont pas mécanisables : la documentation dans le même changement, et le <code>CHANGELOG</code> du registre quand une entrée monte de version.</p><h2 id="documentation-obligatoire" tabindex="-1">Documentation obligatoire <a class="header-anchor" href="#documentation-obligatoire" aria-label="Permalink to &quot;Documentation obligatoire&quot;">​</a></h2><p>Toute évolution structurante doit mettre à jour la documentation dans le même changement. Si aucun document existant ne couvre correctement le sujet, un nouveau fichier Markdown doit être créé dans <code>docs/</code> puis ajouté à l&#39;index.</p><p>Sont notamment concernées : les nouveaux packages, composants majeurs, patterns, commandes CLI, dépendances structurantes, API publiques et conventions internes.</p><p>Un diagramme Mermaid est obligatoire lorsqu&#39;une évolution modifie un flux, les dépendances entre packages ou l&#39;organisation du système.</p><h2 id="ajouter-un-composant" tabindex="-1">Ajouter un composant <a class="header-anchor" href="#ajouter-un-composant" aria-label="Permalink to &quot;Ajouter un composant&quot;">​</a></h2>',12)),(t(),d(u,null,{default:o(()=>[l(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20Need%5B%22Identifier%20un%20usage%20r%C3%A9p%C3%A9t%C3%A9%22%5D%20--%3E%20API%5B%22D%C3%A9finir%20l'API%22%5D%0A%20%20API%20--%3E%20A11y%5B%22D%C3%A9finir%20clavier%20et%20accessibilit%C3%A9%22%5D%0A%20%20A11y%20--%3E%20Layer%7B%22Quel%20niveau%20%3F%22%7D%0A%20%20Layer%20--%3E%7C%22Primitive%22%7C%20P%5B%22Template%20primitive%22%5D%0A%20%20Layer%20--%3E%7C%22Composant%22%7C%20C%5B%22Template%20composant%22%5D%0A%20%20Layer%20--%3E%7C%22Pattern%22%7C%20R%5B%22Template%20pattern%22%5D%0A%20%20P%20--%3E%20Registry%5B%22Ajouter%20au%20registre%22%5D%0A%20%20C%20--%3E%20Registry%0A%20%20R%20--%3E%20Registry%0A%20%20Registry%20--%3E%20Tests%5B%22Tests%20et%20exemple%22%5D%0A%20%20Tests%20--%3E%20Docs%5B%22Mettre%20%C3%A0%20jour%20la%20documentation%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<h2 id="criteres-obligatoires" tabindex="-1">Critères obligatoires <a class="header-anchor" href="#criteres-obligatoires" aria-label="Permalink to &quot;Critères obligatoires&quot;">​</a></h2><ul><li>API publique typée et concise.</li><li>Comportement clavier documenté.</li><li>Labels et relations ARIA corrects.</li><li>États <code>loading</code>, <code>disabled</code>, <code>error</code> ou <code>empty</code> lorsque pertinents.</li><li>Design basé sur les tokens sémantiques.</li><li>Aucun nom d&#39;entreprise, endpoint ou modèle métier.</li><li>Dépendances du registre déclarées explicitement.</li><li>Aucun écrasement silencieux d&#39;un fichier utilisateur.</li><li>Documentation Markdown créée ou mise à jour dans le même changement.</li><li>Un contrôle natif masqué derrière un visuel personnalisé porte <code>sia-visually-hidden</code>, jamais un <code>opacity:0</code> maison : un contrôle seulement transparent reste peint par le navigateur, et son propre dessin clignote sous le nôtre au clic.</li></ul><h2 id="choisir-le-bon-emplacement" tabindex="-1">Choisir le bon emplacement <a class="header-anchor" href="#choisir-le-bon-emplacement" aria-label="Permalink to &quot;Choisir le bon emplacement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Emplacement</th></tr></thead><tbody><tr><td>Valeur visuelle, vocabulaire de ton ou de taille</td><td><code>packages/tokens</code></td></tr><tr><td>Fonction sans dépendance</td><td><code>packages/utils</code></td></tr><tr><td>Appel réseau, greffon, service CRUD</td><td><code>packages/api</code></td></tr><tr><td>Calcul ou machine à états partagée avec le natif</td><td><code>packages/headless</code></td></tr><tr><td>Mécanisme React lié au DOM</td><td><code>packages/react</code></td></tr><tr><td>Composant web</td><td><code>packages/react-web/src/components</code></td></tr><tr><td>Story</td><td><code>apps/docs/src/stories</code></td></tr><tr><td>Explication structurelle</td><td><code>docs</code></td></tr></tbody></table><h2 id="verification-avant-validation" tabindex="-1">Vérification avant validation <a class="header-anchor" href="#verification-avant-validation" aria-label="Permalink to &quot;Vérification avant validation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Une nouvelle entrée doit également être installée dans un dossier temporaire avec la CLI afin de vérifier les chemins et les dépendances transitives.</p><h2 id="ou-ecrire-un-composant-web" tabindex="-1">Où écrire un composant web <a class="header-anchor" href="#ou-ecrire-un-composant-web" aria-label="Permalink to &quot;Où écrire un composant web&quot;">​</a></h2><p>Dans <code>packages/react-web/src/components/&lt;Nom&gt;/</code>, et nulle part ailleurs. Il n&#39;y a plus de gabarits : le registre sert <strong>le fichier source lui-même</strong>, copié octet pour octet par la CLI.</p><p>Deux contraintes viennent de là :</p><ul><li><strong>N&#39;importez rien hors de votre dossier</strong>, à part <code>@sia-ui/*</code> et un autre composant par <code>../&lt;Nom&gt;</code>. La CLI ne copie que <code>components/&lt;Nom&gt;/</code>; un import vers <code>../../hooks</code> arrive cassé chez l&#39;utilisateur. C&#39;est ce qui a rendu l&#39;entrée <code>drawer</code> ininstallable pendant des semaines.</li><li><strong>Déclarez l&#39;entrée dans <code>packages/registry/registry.json</code></strong>, avec ses <code>dependencies</code> et ses <code>registryDependencies</code> — la CLI s&#39;en sert pour tirer ce qui manque et annoncer ce qu&#39;il faut installer.</li></ul><p>Voir <a href="./../fondations/source-unique.html">Source unique des composants</a>.</p><h2 id="ou-ecrire-quoi" tabindex="-1">Où écrire quoi <a class="header-anchor" href="#ou-ecrire-quoi" aria-label="Permalink to &quot;Où écrire quoi&quot;">​</a></h2><p>Le dépôt a un ordre de dépendance : <code>tokens</code> → <code>core</code> → <code>react</code> → <code>react-web</code>. Une chose s&#39;écrit au niveau le plus bas où elle a du sens, et une seule fois.</p><table tabindex="0"><thead><tr><th>Ce que tu écris</th><th>Où</th></tr></thead><tbody><tr><td>Une valeur de thème, une échelle</td><td><code>@sia-ui/tokens</code></td></tr><tr><td>Le vocabulaire partagé web/mobile — ton, taille, variante</td><td><code>@sia-ui/tokens</code></td></tr><tr><td>Un helper pur, sans React</td><td><code>@sia-ui/utils</code></td></tr><tr><td>Un hook de runtime, un provider, un portail</td><td><code>@sia-ui/react</code></td></tr><tr><td>Un composant DOM</td><td><code>@sia-ui/react-web</code></td></tr></tbody></table><p>Avant d&#39;ajouter un helper ou un hook, vérifier qu&#39;il n&#39;existe pas déjà plus bas. Un composant ne réimplémente jamais ce qu&#39;une couche inférieure expose.</p>`,16))])}const C=n(p,[["render",m]]);export{k as __pageData,C as default};
